{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, the closest analogue (Morgan 0.373), has very low absolute oral bioavailability (~4.9%) in patients, but this is driven by first-pass reduction of its ketone, a liability absent in the query's lactam, so it is only weak contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C46"],
      "claim": "Donepezil, which shares the dimethoxybenzene and basic-amine features, has essentially complete oral bioavailability (~100%) in humans, supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a tetrabenazine analogue modified for oral delivery, has absolute oral bioavailability ~49% in humans, showing that tetrabenazine-like scaffolds can achieve F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, a large dimethoxy-tetrahydroisoquinoline amide, has low absolute oral bioavailability (~11%), indicating that large dimethoxyaryl amides can have poor F; this is a concern for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C50"],
      "claim": "Verapamil, which shares the bis-dimethoxyphenyl tertiary-amine motif, has absolute oral bioavailability ~22% in normal subjects, just above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Noscapine, a dimethoxybenzene-containing alkaloid with a basic amine, has absolute oral bioavailability ~30% in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Urapidil, a methoxyphenyl tertiary-amine drug, has absolute oral bioavailability ~78%, supporting high F for the query's basic amine-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Gallopamil, a verapamil-like dimethoxyphenyl tertiary amine, is reported to have ~96% oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction: high. The closest analogue tetrabenazine has low F, but its low-F mechanism (ketone reduction) does not apply to the query's lactam. Multiple moderately similar molecules sharing the dimethoxybenzene/basic-amine pharmacophore (donepezil, valbenazine, noscapine, urapidil, gallopamil) have F ≥30–100%, and verapamil, which shares the bis-dimethoxyphenyl tertiary-amine motif, has F ~22%. These outweigh the weak low-F signals from tetrabenazine and almorexant, supporting F ≥20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "Tetrabenazine's low-F mechanism (ketone reduction) is not present in the query, so its relevance is uncertain.",
    "Verapamil's F is borderline around the 20% threshold; small differences in absorption or first-pass metabolism could change the classification.",
    "The impact of the query's low neutral fraction (pKa 9.05) on human intestinal absorption is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

